'use strict';
const KEY = 'bitacora-pc-v1';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh = () => ({version:1,profile:{name:'',group:'',mode:'Simulación'},missions:{},updated:null});
let storageOK = true, state = fresh(), filter = 'Todas', query = '', toastTimer;
try { const raw = localStorage.getItem(KEY); if (raw) state = validateBackup(JSON.parse(raw)); } catch { storageOK = false; }
function record(id) {
  if (!state.missions[id]) state.missions[id] = {answers:{},evidence:['','',''],score:null,attempts:[],trials:[],report:[],checks:[],order:null,sim:{},seen:[]};
  return state.missions[id];
}
function save() {
  state.updated = new Date().toISOString();
  try { localStorage.setItem(KEY, JSON.stringify(state)); storageOK = true; } catch { storageOK = false; toast('No se pudo guardar en el navegador. Descarga una copia JSON antes de salir.'); }
}
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('show'), 4200); }
function evidenceOK(m) { return record(m.id).evidence.every(t => t.trim().length >= 40); }
function reportOK(m) { const r = record(m.id); return m.type !== 'report' || (Array.from({length:6},(_,i) => (r.report[i] || '').trim().length >= 40).every(Boolean) && [0,1,2,3].every(i => r.checks[i])); }
function complete(m) { return record(m.id).score >= 80 && record(m.id).score !== null && evidenceOK(m) && reportOK(m); }
function totals() { const done = MISSIONS.filter(complete).length; const xp = MISSIONS.reduce((s,m) => s + (complete(m) ? 100 : 0),0); return {done,xp,p:Math.round(done/12*100)}; }
function status(m) { const r=record(m.id); return complete(m) ? 'Completada' : r.attempts.length || Object.keys(r.answers).length || r.evidence.some(Boolean) || r.trials.length || r.report.some(Boolean) ? 'En curso' : 'Por explorar'; }
const svg = (content, view='0 0 100 90') => `<svg viewBox="${view}" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${content}</svg>`;
function icon(name) {
  const stroke='stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"';
  const shapes={
    shield:'<path d="M50 9 77 20v23c0 18-16 31-27 37-11-6-27-19-27-37V20Z"/><path d="m36 43 10 10 18-23"/><path d="M14 32h-7m79 0h7M16 62l-5 5m73-5 5 5"/>',
    tools:'<path d="m62 15-8 19 12 7 13-16c4 19-8 29-21 25L30 78c-10 6-18-4-11-12l29-27c-5-15 1-24 14-24Z"/><circle cx="27" cy="71" r="3"/><path d="m19 17 11-5 12 17-8 9Zm17 19 33 34m0 0 9 8 6-6-10-10"/>',
    board:'<rect x="18" y="10" width="65" height="71" rx="4"/><rect x="35" y="22" width="25" height="25" rx="2"/><path d="M67 20v33m7-33v33M28 60h38m-38 9h27M25 23v22m13 9h10"/><circle cx="71" cy="69" r="5"/><path d="M30 10V5m41 5V5M83 28h6m-6 15h6M18 58h-6"/>',
    chip:'<rect x="27" y="21" width="48" height="48" rx="4"/><rect x="37" y="31" width="28" height="28" rx="2"/><path d="M36 21V10m14 11V10m14 11V10M36 69v11m14-11v11m14-11v11M27 31H16m11 14H16m11 14H16m59-28h11M75 45h11M75 59h11"/>',
    fan:'<circle cx="50" cy="45" r="32"/><circle cx="50" cy="45" r="7"/><path d="M46 38c-17-18 5-34 12-19 4 8-1 16-5 20M57 45c24-7 28 20 12 19-9-1-14-9-15-13M47 52c-6 24-31 13-23 0 5-8 15-8 20-6"/><path d="M12 45H3m94 0h-9M50 4v8m0 66v8"/>',
    layers:'<path d="m50 11 36 18-36 18-36-18 36-18Zm-35 32 35 18 35-18M15 57l35 18 35-18"/>',
    bolt:'<rect x="19" y="15" width="62" height="60" rx="6"/><path d="m53 25-16 24h13l-4 15 17-24H50Z"/><path d="M29 9v6m41-6v6M29 75v7m41-7v7"/>',
    terminal:'<rect x="10" y="15" width="80" height="60" rx="6"/><path d="M10 29h80M21 22h1m7 0h1m7 0h1M25 43l12 9-12 9m22 0h21"/>',
    search:'<circle cx="43" cy="38" r="25"/><path d="m61 57 23 23M30 38h26M43 25v26"/>',
    book:'<path d="M50 24C35 12 18 14 11 19v51c15-7 26-3 39 6m0-52c15-12 32-10 39-5v51c-15-7-26-3-39 6V24ZM23 30l15 3m-15 9 15 3m24-12 15-3M62 45l15-3"/>',
    report:'<path d="M25 9h34l18 18v54H25V9Zm33 0v19h19M36 42h29M36 53h29M36 64h16"/><path d="m56 68 5 5 10-12"/>'
  };
  return svg(`<g ${stroke}>${shapes[name] || shapes.chip}</g>`);
}
function heroArt() {
  return `<div class="hero-art"><span class="art-label">VIRTUAL WORKSPACE / 01</span>${svg(`<defs><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0v22" stroke="#6d9450" stroke-opacity=".12"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="12" stdDeviation="9" flood-color="#426536" flood-opacity=".22"/></filter></defs><rect width="420" height="300" fill="url(#grid)"/><ellipse cx="222" cy="251" rx="155" ry="19" fill="#87a36b" opacity=".17"/><g transform="translate(72 46) rotate(-13 135 105) skewX(10)" filter="url(#shadow)"><path d="M0 17 248 0l21 175L17 201Z" fill="#315e42" stroke="#204c32" stroke-width="4"/><path d="m17 29 217-15 17 145L33 180Z" fill="#406c48" stroke="#6e9152"/><g stroke="#8dae68" stroke-width="1.5" opacity=".7"><path d="m31 60 48-3 10 88 74-5M24 80l40-3 5 65M130 28l4 19 70-5 8 73m-94 54 7-18 80-8m-30-112 6 30 43-2"/><path d="m101 30 3 18m-5 57-26 3m51-4 2 29 53-4"/></g><g fill="#c6d0b2" stroke="#b0c69b"><rect x="88" y="47" width="74" height="65" rx="3"/><rect x="99" y="57" width="52" height="45" rx="3" fill="#dedfd0"/><path d="M111 62v35m8-35v35m8-35v35m8-35v35m8-35v35" stroke="#b2bea2"/></g><g fill="#bcc38c"><rect x="179" y="37" width="10" height="74" rx="2"/><rect x="196" y="36" width="10" height="74" rx="2"/></g><path d="m64 138 149-10 2 11-150 12Z" fill="#1c392b" stroke="#a6bc7a"/><path d="m78 160 96-7 1 9-96 7Z" fill="#172e21"/><g fill="#b4bdb1" stroke="#284d37"><rect x="9" y="32" width="22" height="30" rx="2"/><rect x="13" y="70" width="22" height="24" rx="2"/><rect x="17" y="104" width="22" height="22" rx="2"/></g><g fill="#c4cfaa"><circle cx="51" cy="52" r="5"/><circle cx="59" cy="51" r="5"/><circle cx="53" cy="66" r="5"/><circle cx="61" cy="65" r="5"/><circle cx="229" cy="141" r="13"/></g><g fill="#d2deba"><circle cx="29" cy="25" r="3"/><circle cx="229" cy="17" r="3"/><circle cx="40" cy="169" r="3"/><circle cx="248" cy="163" r="3"/></g></g><g transform="translate(291 181) rotate(18)"><rect width="54" height="54" rx="7" fill="#d7dcce" stroke="#7b9367" stroke-width="2"/><rect x="9" y="9" width="36" height="36" rx="4" fill="#eff0e5"/><text x="27" y="32" text-anchor="middle" fill="#688056" font-family="monospace" font-size="11">CPU</text></g><g transform="translate(30 216)"><rect width="116" height="26" rx="5" fill="#f5f8ed" stroke="#bdcfa9"/><circle cx="13" cy="13" r="4" fill="#7da254"/><text x="25" y="17" fill="#567340" font-family="monospace" font-size="8">MODO SIMULACIÓN</text></g>`, '0 0 420 300')}</div>`;
}
function pageHeading(title,sub,tag='APRENDIZAJE AUTÓNOMO'){return `<div class="page-heading"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${sub}</p></div><span class="pill"><span class="tiny-dot"></span> Laboratorio en casa</span></div>`;}
function card(m){const s=status(m); return `<a class="mission-card" href="#mision/${m.id}"><div class="card-visual ${m.color}"><span class="card-no">MISIÓN ${m.id}</span>${icon(m.icon)}<span class="card-kind">${m.kind}</span></div><div class="card-body"><span class="card-kicker">${m.stage} · ${m.minutes} min</span><h3>${m.title}</h3><p>${m.desc}</p><div class="card-foot"><span>${complete(m)?'✓ Completada':s==='En curso'?'◉ En curso':'○ '+m.kind}</span><span class="card-start">${complete(m)?'Repasar':s==='En curso'?'Continuar':'Explorar'} ↗</span></div></div></a>`;}
function dashboard(){const t=totals(), next=MISSIONS.find(m=>!complete(m)) || MISSIONS[0]; return `
  ${pageHeading(state.profile.name ? `Tu siguiente paso, ${esc(state.profile.name.split(' ')[0])}.`:'Tu próximo reto empieza aquí.','Aprende a mantener, diagnosticar y cuidar un computador. Una misión a la vez.')}
  <section class="hero"><div class="hero-copy"><div class="eyebrow">APRENDER · EXPERIMENTAR · DOCUMENTAR</div><h2>Convierte tu casa<br>en un laboratorio<br>de buenas decisiones.</h2><p>12 misiones para llevar la guía de mantenimiento a la práctica, a tu ritmo y con evidencia.</p><a class="btn" href="#mision/${next.id}">${t.done?'Continuar mi ruta':'Comenzar mi primera misión'} <span>↗</span></a><div class="hero-meta"><span>◷ 8 horas de trabajo</span><span>◇ 100 % virtual</span><span>↻ Intentos libres</span></div></div>${heroArt()}</section>
  <div class="stat-grid"><div class="stat"><span class="stat-icon">◇</span><div><b>${t.done}<span style="font-size:12px;color:#8c9987"> /12</span></b><small>Misiones completadas</small></div></div><div class="stat"><span class="stat-icon">◷</span><div><b>8 h</b><small>Ruta sugerida en 4 sesiones</small></div></div><div class="stat"><span class="stat-icon">✧</span><div><b>${t.xp}<span style="font-size:12px;color:#8c9987"> XP</span></b><small>100 XP por misión completa</small></div></div><div class="stat"><span class="stat-icon">▤</span><div><b>${MISSIONS.filter(evidenceOK).length}</b><small>Evidencias desarrolladas</small></div></div></div>
  ${!storageOK?'<div class="notice amber">El almacenamiento local no está disponible o la copia guardada no pudo leerse. Descarga una copia JSON al terminar para conservar tu trabajo.</div>':''}
  <div class="dashboard-grid"><section><div class="section-head"><div><h2>Tu ruta de aprendizaje</h2><p>Empieza por lo esencial. Avanza hacia el diagnóstico.</p></div><a class="text-link" href="#misiones">Ver las 12 misiones ↗</a></div><div class="mission-grid">${MISSIONS.slice(0,4).map(card).join('')}</div></section><aside><div class="panel"><h3>Así va tu recorrido</h3><div class="progress-circle" style="--p:${t.p}"><span><b>${t.p}%</b><small>DE LA RUTA COMPLETA</small></span></div><div class="mini-row"><span>Misiones por completar</span><b>${12-t.done}</b></div><div class="mini-row"><span>Tu nivel</span><b>${t.done>=9?'Resolutor':t.done>=4?'Explorador':'Aprendiz'}</b></div><p class="help" style="margin-top:12px">Completa el reto y sus tres evidencias para sumar avance.</p><a href="#portafolio" class="btn secondary small" style="width:100%">Abrir mi portafolio ↗</a></div><div class="panel tip-panel"><div class="eyebrow">◈ UNA IDEA PARA TU TALLER</div><h3>Primero observa.<br>Después interviene.</h3><p>Un síntoma no confirma una falla. Registra las pistas antes de proponer una solución.</p><a class="text-link" href="#recursos">Consultar material de apoyo ↗</a></div></aside></div>`;}
function missionList(){return `${pageHeading('Una ruta. Doce misiones.','Preparar → Intervenir → Diagnosticar → Documentar. Puedes repasar cualquier actividad.','RUTA DE APRENDIZAJE')}<div class="notice">Para completar una misión: logra al menos 80 % en el reto y desarrolla las tres evidencias (mínimo 40 caracteres cada una). Los laboratorios requieren tres pruebas y el proyecto final incluye su lista de control. El instructor valora la calidad.</div><div class="filters" role="group" aria-label="Filtrar misiones">${['Todas','Preparar','Intervenir','Diagnosticar','Documentar'].map(f=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}<input class="input search" id="search" type="search" aria-label="Buscar una misión" placeholder="Buscar tema o misión…" value="${esc(query)}"></div><div class="mission-grid" id="mission-results">${filteredCards()}</div>`;}
function filteredCards(){const items=MISSIONS.filter(m=>(filter==='Todas'||m.stage===filter)&&(m.title+' '+m.desc+' '+m.kind+' '+m.id).toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es'))); return items.length?items.map(card).join(''):'<p class="empty">No hay misiones para esa búsqueda. Prueba con otro tema.</p>';}
function questionBlock(m,i,disabled=false){const q=m.questions[i], r=record(m.id); return `<fieldset class="q" ${disabled?'disabled':''}><legend>${esc(q.q)}</legend>${q.options.map((o,j)=>`<label class="option"><input type="radio" name="q-${m.id}-${i}" data-answer="q${i}" value="${j}" ${String(r.answers['q'+i])===String(j)?'checked':''}><span>${esc(o)}</span></label>`).join('')}<div id="feedback-q${i}" class="feedback" aria-live="polite"></div></fieldset>`;}
function matchBlock(m){const r=record(m.id), options=m.pairs.map(p=>p[1]).sort((a,b)=>a.localeCompare(b,'es')); return `<p class="help">Selecciona una función por elemento. Cada función corresponde a un único elemento.</p>${m.pairs.map((p,i)=>`<div class="match-row"><label for="match-${i}">${esc(p[0])}</label><select id="match-${i}" data-answer="p${i}"><option value="">Selecciona una opción…</option>${options.map(o=>`<option value="${esc(o)}" ${r.answers['p'+i]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div><div id="feedback-p${i}" class="feedback" aria-live="polite"></div>`).join('')}`;}
function boardBlock(m){const positions=[[110,70],[230,62],[95,168],[115,216],[30,55],[245,237]],r=record(m.id); return `<div class="sim-visual">${svg(`<rect x="10" y="10" width="290" height="265" rx="9" fill="#365a3e" stroke="#a6c58e"/><rect x="76" y="35" width="85" height="80" rx="4" stroke="#bdd19d" stroke-width="3"/><path d="M211 31v108m14-108v108m14-108v108M55 166h173m-153 50h90" stroke="#b4c482" stroke-width="8"/><path d="M27 30v76m22-76v76" stroke="#8fb175" stroke-width="8"/><rect x="221" y="225" width="59" height="25" fill="#a8bb81"/>${positions.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="13" fill="#e6edb8"/><text x="${p[0]}" y="${p[1]+4}" text-anchor="middle" fill="#294531" font-size="12" font-family="monospace">${i+1}</text>`).join('')}`,'0 0 310 285')}<small>Esquema conceptual · La distribución cambia según el modelo</small></div><div class="filters">${m.pairs.map((p,i)=>`<button class="chip" data-board="${i}">${i+1}. ${p[0]}</button>`).join('')}</div><div id="board-hint" class="notice" aria-live="polite">Explora los puntos numerados del mapa antes de asociar las funciones.</div>${matchBlock(m)}`;}
function orderBlock(m){const r=record(m.id); if (!r.order) r.order=[3,0,5,2,4,1]; return `<p class="help">Mueve cada etapa con ↑ y ↓ hasta formar una secuencia coherente.</p><ol class="order-list">${r.order.map((n,i)=>`<li><span>${esc(m.items[n])}</span><button type="button" data-move="${i}" data-dir="-1" aria-label="Subir etapa: ${esc(m.items[n])}" ${i===0?'disabled':''}>↑</button><button type="button" data-move="${i}" data-dir="1" aria-label="Bajar etapa: ${esc(m.items[n])}" ${i===5?'disabled':''}>↓</button></li>`).join('')}</ol><div id="feedback-order" class="feedback" aria-live="polite"></div>`;}
function labControls(m){const r=record(m.id),v=r.sim;
  if(m.type==='thermal')return `<div class="sim-grid"><div class="sim-visual" id="sim-visual"></div><div><div class="sim-control"><label for="coverage">Cobertura en el modelo <output id="coverage-label"></output></label><input id="coverage" type="range" min="20" max="100" step="10" value="${v.coverage??40}" data-sim="coverage"></div><label class="field">Estado de las superficies<select data-sim="clean"><option value="0" ${v.clean!=='1'?'selected':''}>Residuos de la interfaz anterior</option><option value="1" ${v.clean==='1'?'selected':''}>Limpias y secas según procedimiento</option></select></label><label class="field">Presión del montaje<select data-sim="even"><option value="0" ${v.even!=='1'?'selected':''}>Desigual: un tornillo al máximo primero</option><option value="1" ${v.even==='1'?'selected':''}>Uniforme y conforme al manual</option></select></label><button class="btn light small" data-action="trial">+ Registrar configuración</button></div></div><p class="help">Índice de contacto didáctico (0–100): cobertura × factores de limpieza y uniformidad. No es eficiencia real ni una temperatura.</p><div id="trial-table">${trialTable(m)}</div>${m.questions.map((_,i)=>questionBlock(m,i)).join('')}`;
  return `<div class="sim-grid"><div class="sim-visual" id="sim-visual"></div><div>${[['intake','Entrada efectiva supuesta',60],['exhaust','Salida efectiva supuesta',100]].map(([k,label,defaultValue])=>`<div class="sim-control"><label for="${k}">${label}<output id="${k}-label"></output></label><input id="${k}" type="range" min="20" max="160" step="10" value="${v[k]??defaultValue}" data-sim="${k}"></div>`).join('')}<button class="btn light small" data-action="trial">+ Registrar configuración</button><p class="help" style="margin-top:15px">Los valores ya representan caudal efectivo supuesto. Este modelo no calcula RPM, pérdidas en filtros ni presión estática.</p></div></div><div id="trial-table">${trialTable(m)}</div>${m.questions.map((_,i)=>questionBlock(m,i)).join('')}`;
}
function simValues(m){const v=record(m.id).sim; return m.type==='thermal'?{coverage:Number(v.coverage??40),clean:v.clean==='1',even:v.even==='1'}:{intake:Number(v.intake??60),exhaust:Number(v.exhaust??100)};}
function contactIndex(v){return Math.round(v.coverage*(v.clean?1:.55)*(v.even?1:.65));}
function updateSim(m){const v=simValues(m),target=$('#sim-visual');if(!target)return;
  if(m.type==='thermal'){const value=contactIndex(v);$('#coverage-label').textContent=v.coverage+' %';target.innerHTML=`${svg(`<rect x="21" y="12" width="58" height="58" rx="5" fill="#94aa85" stroke="#cfdfb7" stroke-width="2"/><rect x="${50-24*Math.sqrt(v.coverage/100)}" y="${41-24*Math.sqrt(v.coverage/100)}" width="${48*Math.sqrt(v.coverage/100)}" height="${48*Math.sqrt(v.coverage/100)}" rx="5" fill="${v.clean?'#dbe5ce':'#918b6e'}"/><path d="M15 15h-5m5 52h-5m75-52h5m-5 52h5" stroke="#b6d88a" stroke-width="3"/>`)}<strong>${value}/100</strong><small>ÍNDICE DIDÁCTICO DE CONTACTO</small><div class="meter" style="width:100%">${Array.from({length:10},(_,i)=>`<span class="${value>i*10?'on':''}"></span>`).join('')}</div>`;
  }else{const delta=v.intake-v.exhaust;$('#intake-label').textContent=v.intake+' CFM';$('#exhaust-label').textContent=v.exhaust+' CFM';target.innerHTML=`${svg(`<rect x="19" y="12" width="65" height="64" rx="3" stroke="#8da779" stroke-width="2"/><rect x="36" y="25" width="24" height="24" rx="2" fill="#365d3d" stroke="#a9c38b"/><path d="M41 57h30" stroke="#8ca06e" stroke-width="5"/><path d="M94 34H66m9-5-9 5 9 5M37 34H8m9-5-9 5 9 5M64 21V5m-5 8 5-8 5 8" stroke="#b8ed75" stroke-width="3"/><text x="87" y="57" fill="#c7d9b3" font-size="7">IN</text><text x="2" y="57" fill="#c7d9b3" font-size="7">OUT</text>`)}<strong>${delta>0?'+':''}${delta} CFM</strong><small>BALANCE ${delta>10?'POSITIVO':delta< -10?'NEGATIVO':'SIMILAR / EQUILIBRADO'}</small>`;}
}
function trialTable(m){const rows=record(m.id).trials;if(!rows.length)return '<div class="notice">Aún no has registrado pruebas. Guarda tres configuraciones diferentes.</div>';return `<div class="table-wrap"><table><caption class="help">Pruebas registradas · ${rows.length}/3 mínimo</caption><thead><tr><th>Prueba</th>${m.type==='thermal'?'<th>Cobertura</th><th>Superficies / presión</th><th>Índice</th>':'<th>Entrada</th><th>Salida</th><th>Balance</th>'}</tr></thead><tbody>${rows.map((v,i)=>`<tr><td>${i+1}</td>${m.type==='thermal'?`<td>${v.coverage} %</td><td>${v.clean?'Limpias':'Residuos'} / ${v.even?'uniforme':'desigual'}</td><td>${contactIndex(v)}/100</td>`:`<td>${v.intake} CFM</td><td>${v.exhaust} CFM</td><td>${v.intake-v.exhaust} CFM</td>`}</tr>`).join('')}</tbody></table></div>`;}
function psuBlock(m){const r=record(m.id);return `<div class="notice amber">Solo interpretación de datos ficticios. No abras fuentes, no hagas puentes ni midas circuitos energizados en casa. La tolerancia de ±5 % se aplica aquí únicamente a los tres rieles positivos indicados.</div><p class="help">Límite inferior = nominal × 0,95. Límite superior = nominal × 1,05. Los extremos se consideran incluidos.</p><div class="reading-grid">${m.readings.map((v,i)=>`<div class="reading"><span>Riel ${v.rail}</span><strong>${v.value.toLocaleString('es-CO')} V</strong><label class="help" for="rail-${i}">Lectura simulada</label><select id="rail-${i}" data-answer="r${i}"><option value="">Clasificar…</option><option value="inside" ${r.answers['r'+i]==='inside'?'selected':''}>Dentro del intervalo</option><option value="outside" ${r.answers['r'+i]==='outside'?'selected':''}>Fuera del intervalo</option></select><div id="feedback-r${i}" class="feedback"></div></div>`).join('')}</div>${m.questions.map((_,i)=>questionBlock(m,i)).join('')}`;}
function consoleBlock(m){return `<div class="notice">Consola didáctica: estos botones solo cambian el texto de la web. No ejecutan órdenes en Windows.</div><div class="filters">${CONSOLE_COMMANDS.map((c,i)=>`<button class="chip" data-command="${i}">${c.name}</button>`).join('')}</div><div class="terminal" id="terminal-output" role="status">Selecciona un comando para ver un ejemplo de salida simulada.</div><div id="command-note" class="help" style="margin:12px 0"></div>${matchBlock(m)}`;}
function caseBlock(m){const r=record(m.id);let current=0;while(current<m.questions.length&&r.answers['q'+current]===m.questions[current].answer&&r.seen.includes(current)) current++;return `<p class="help">Avanza investigando. Puedes cambiar una decisión previa; las pistas posteriores volverán a requerir verificación.</p>${m.questions.map((_,i)=>i<=current?`<div class="case-step">${questionBlock(m,i)}${r.seen.includes(i)&&r.answers['q'+i]===m.questions[i].answer?`<div class="feedback good">${esc(m.questions[i].why)}</div>`:''}${i===current?`<button class="btn light small" data-case="${i}">Comprobar decisión y revelar pista →</button>`:''}</div>`:'').join('')}${current===m.questions.length?'<div class="achievement">✓ Investigación resuelta. Verifica el reto completo y redacta el cierre del ticket.</div>':''}`;}
const reportChecks=['Distinguí datos simulados de observaciones reales.','Mis conclusiones se apoyan en evidencias y declaran límites.','Mi plan protege a las personas, el equipo y los datos.','Mis recomendaciones incluyen una validación y un criterio de seguimiento.'];
function reportBlock(m){const r=record(m.id);return `<div class="notice">El informe es una evidencia de aprendizaje. No es un certificado de servicio ni una aprobación oficial de competencia.</div>${m.fields.map((f,i)=>`<label class="field">${i+1}. ${f}<textarea data-report="${i}" rows="4" maxlength="6000" placeholder="Desarrolla esta sección con datos y decisiones de tu caso…">${esc(r.report[i]||'')}</textarea><span class="evidence-count" data-report-count="${i}">${(r.report[i]||'').trim().length}/40 caracteres mínimo</span></label>`).join('')}<h3>Lista de control del informe</h3><div class="report-checks">${reportChecks.map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${r.checks[i]?'checked':''}><span>${s}</span></label>`).join('')}</div>`;}
function activity(m){switch(m.type){case 'quiz':return m.questions.map((_,i)=>questionBlock(m,i)).join('');case 'match':return matchBlock(m);case 'board':return boardBlock(m);case 'order':return orderBlock(m);case 'thermal':case 'airflow':return labControls(m);case 'psu':return psuBlock(m);case 'console':return consoleBlock(m);case 'case':return caseBlock(m);case 'report':return reportBlock(m);}}
function lesson(m){const r=record(m.id);return `<div class="lesson-head"><a href="#misiones" class="text-link">← Volver a la ruta</a><div class="eyebrow" style="margin-top:22px">MISIÓN ${m.id} / 12 · ${m.stage} · ${m.minutes} MIN</div><h1>${m.title}</h1><p>${m.goal}</p><span class="badge">${m.kind}</span> <span id="mission-status" class="status-text">${status(m)}</span></div><div class="lesson-layout"><div><section class="lesson-box"><h2>01 / Tu encargo</h2><p class="muted">${m.context}</p><ol class="steps">${m.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="actions">${m.sections.map(s=>`<a class="btn secondary small" href="${SOURCE}#${s}" target="_blank" rel="noopener">Leer: ${sectionName(s)} ↗</a>`).join('')}</div></section><section class="lesson-box" id="activity"><h2>02 / Resuelve el reto</h2>${activity(m)}<div class="actions"><button class="btn" data-action="grade">Verificar mi trabajo <span>→</span></button><span class="help">Intentos libres · Retroalimentación formativa</span></div><div id="grade-summary" class="feedback" aria-live="polite">${r.score!==null?`Último resultado: ${r.score} %. ${r.score>=80?'Reto alcanzado. Revisa tus evidencias.':'Revisa la retroalimentación y vuelve a intentarlo.'}`:''}</div></section><section class="lesson-box" id="evidence"><h2>03 / Deja una evidencia que explique</h2><p class="muted">Responde con tus palabras. Describe tus dibujos o notas; no es necesario subir imágenes. Cada campo requiere al menos 40 caracteres. La extensión no sustituye la calidad.</p>${m.evidence.map((s,i)=>`<label class="field">${i+1}. ${s}<textarea data-evidence="${i}" rows="3" maxlength="6000" placeholder="Explica qué observaste, por qué y cómo lo aplicarías…">${esc(r.evidence[i])}</textarea><span class="evidence-count" data-evidence-count="${i}">${r.evidence[i].trim().length}/40 caracteres mínimo</span></label>`).join('')}<div class="actions"><button class="btn light" data-action="save-evidence">Guardar evidencia y revisar avance →</button><a href="#portafolio" class="text-link">Ver mi portafolio</a></div><div id="completion-message" class="feedback" aria-live="polite"></div></section><div class="actions">${m.id!=='01'?`<a class="btn secondary" href="#mision/${String(Number(m.id)-1).padStart(2,'0')}">← Misión anterior</a>`:''}${m.id!=='12'?`<a class="btn" href="#mision/${String(Number(m.id)+1).padStart(2,'0')}">Siguiente misión →</a>`:'<a class="btn" href="#portafolio">Preparar mi entrega →</a>'}</div></div><aside><div class="panel"><h3>Tu lista de ruta</h3><p class="help">Tres pasos para completar la misión.</p><ol class="steps"><li>Lee las secciones de referencia.</li><li>Obtén al menos 80 % en el reto.</li><li>Desarrolla tus tres evidencias.</li></ol><div class="mini-row"><span>Intentos registrados</span><b id="attempt-count">${r.attempts.length}</b></div><div class="mini-row"><span>Mejor resultado</span><b id="best-score">${r.attempts.length?Math.max(...r.attempts.map(a=>a.score))+' %':'—'}</b></div><div class="mini-row"><span>Recompensa</span><b>100 XP al completar</b></div></div><div class="panel tip-panel"><div class="eyebrow">APRENDIZAJE SEGURO</div><h3>Sin equipo también se aprende.</h3><p>Usa el caso y los laboratorios virtuales. En casa no se requiere abrir equipos, medir voltajes ni ejecutar comandos reales.</p><a href="#recursos" class="text-link">Ver alternativas y materiales ↗</a></div><div class="panel"><h3>Guarda tu recorrido</h3><p class="help">El trabajo se conserva en este navegador. Descarga una copia JSON para continuar en otro dispositivo o evitar pérdidas al borrar los datos.</p><button class="btn secondary small" data-action="backup">Descargar copia JSON ↓</button></div></aside></div>`;}
function sectionName(s){return ({introduccion:'Introducción',seguridad:'Seguridad ESD',herramientas:'Herramientas',motherboard:'Placa base',glosario:'Glosario',taller:'Taller virtual','protocolo-hardware':'Hardware',procedimientos:'Procedimientos','simulador-termico':'Pasta térmica','simulador-flujo':'Flujo de aire','thermal-pads':'Pads y rodamientos','sonda-psu':'Sonda PSU','protocolo-software':'Software',diagnostico:'Diagnóstico',checklist:'Checklist y reporte'})[s]||s;}
function currentMission(){return MISSIONS.find(m=>location.hash==='#mision/'+m.id);}
function invalidate(m){record(m.id).score=null;$('#mission-status') && ($('#mission-status').textContent=status(m));const summary=$('#grade-summary');if(summary){summary.className='feedback';summary.textContent='Hay cambios en el reto. Verifica de nuevo para actualizar el resultado.';}}
function evaluate(m){const r=record(m.id), results=[];
  const add=(key,correct,why)=>results.push({key,correct,why});
  if(['match','board','console'].includes(m.type))m.pairs.forEach((p,i)=>add('p'+i,r.answers['p'+i]===p[1],`${p[0]}: ${p[1]}.`));
  if(m.questions)m.questions.forEach((q,i)=>add('q'+i,Number(r.answers['q'+i])===q.answer && r.answers['q'+i]!==undefined && (m.type!=='case'||r.seen.includes(i)),q.why));
  if(m.type==='order'){const correct=r.order.every((n,i)=>n===i);add('order',correct,correct?'El orden incorpora registro y autorización, aislamiento, control ESD, intervención, revisión y validación.':'Revisa dependencias: primero registrar y autorizar, luego aislar; preparar ESD antes de intervenir; revisar el reensamble antes de energizar y validar.');}
  if(m.type==='psu')m.readings.forEach((v,i)=>add('r'+i,r.answers['r'+i]===(v.ok?'inside':'outside'),`Intervalo: ${(v.nominal*.95).toFixed(3)} a ${(v.nominal*1.05).toFixed(3)} V. Lectura ${v.ok?'dentro':'fuera'} del intervalo.`));
  if(['thermal','airflow'].includes(m.type)){
    const unique=r.trials.length>=3;add('trials',unique,'Se requieren al menos tres configuraciones diferentes registradas.');
    if(m.type==='airflow'){const signs=r.trials.map(v=>v.intake-v.exhaust);add('scenarios',signs.some(d=>d>10)&&signs.some(d=>d< -10)&&signs.some(d=>Math.abs(d)<=10),'Registra un balance positivo (>10), negativo (<−10) y similar (entre −10 y +10 CFM).');}
  }
  if(m.type==='report'){m.fields.forEach((_,i)=>add('report'+i,(r.report[i]||'').trim().length>=40,`La sección ${i+1} requiere al menos 40 caracteres.`));add('checks',[0,1,2,3].every(i=>r.checks[i]),'Revisa y marca las cuatro afirmaciones del control del informe.');}
  let score=Math.round(results.filter(x=>x.correct).length/results.length*100);
  if(['thermal','airflow'].includes(m.type)&&results.some(x=>['trials','scenarios'].includes(x.key)&&!x.correct))score=Math.min(score,79);
  if(m.type==='case'&&r.seen.length<4)score=Math.min(score,79);
  if(m.type==='report'&&!reportOK(m))score=Math.min(score,79);
  return {score,results};
}
function grade(m){const r=record(m.id),result=evaluate(m);r.score=result.score;r.attempts.push({score:r.score,date:new Date().toISOString()});if(r.attempts.length>50)r.attempts.shift();save();result.results.forEach(x=>{const el=$('#feedback-'+x.key);if(el){el.className='feedback '+(x.correct?'good':'bad');el.textContent=(x.correct?'✓ ':'↻ ')+x.why;}});const extra=result.results.filter(x=>!x.correct&&!$('#feedback-'+x.key)).map(x=>x.why);const el=$('#grade-summary');el.className='feedback '+(r.score>=80?'good':'bad');el.textContent=`Resultado: ${r.score} %. ${r.score>=80?'Reto alcanzado. Completa o revisa tus evidencias.':'Revisa las pistas y vuelve a intentarlo.'} ${extra.join(' ')}`;$('#attempt-count').textContent=r.attempts.length;$('#best-score').textContent=Math.max(...r.attempts.map(a=>a.score))+' %';updateCompletion(m);}
function updateCompletion(m){$('#mission-status').textContent=status(m);const el=$('#completion-message');if(!el)return;el.className='feedback '+(complete(m)?'good':'');el.textContent=complete(m)?'✓ Misión completada. Tus 100 XP ya están en el portafolio. El instructor revisará la calidad de tus explicaciones.':`Tu trabajo está guardado${storageOK?' en este navegador':' solo en esta sesión: descarga una copia'}. ${record(m.id).score===null?'Falta verificar el reto.':record(m.id).score<80?'Falta alcanzar el 80 % en el reto.':''} ${!evidenceOK(m)?'Desarrolla las tres evidencias con al menos 40 caracteres cada una.':''} ${!reportOK(m)?'Completa las seis secciones y las cuatro comprobaciones del informe.':''}`;}
function evidenceContent(m){const r=record(m.id);return `<div class="evidence-item"><h3>${m.id}. ${m.title}</h3><p class="help">${status(m)} · Último resultado: ${r.score===null?'sin verificar':r.score+' %'} · Intentos: ${r.attempts.length} · Mejor: ${r.attempts.length?Math.max(...r.attempts.map(a=>a.score))+' %':'—'}</p>${r.trials.length?trialTable(m):''}${m.type==='report'?m.fields.map((f,i)=>`<h4>${i+1}. ${f}</h4><p class="text-block">${esc(r.report[i]||'Sin desarrollar.')}</p>`).join(''):''}${m.evidence.map((s,i)=>`<h4 style="font-size:12px;margin-top:18px">${i+1}. ${s}</h4><p class="text-block">${esc(r.evidence[i]||'Sin desarrollar.')}</p>`).join('')}<details><summary>Respuestas y trazabilidad</summary>${answerTrace(m)}</details></div>`;}
function answerTrace(m){const r=record(m.id);let lines=[];if(m.questions)lines.push(...m.questions.map((q,i)=>`${q.q}\nRespuesta: ${q.options[r.answers['q'+i]]||'Sin responder'}`));if(m.pairs)lines.push(...m.pairs.map((p,i)=>`${p[0]} → ${r.answers['p'+i]||'Sin responder'}`));if(m.type==='order')lines.push(...(r.order||[]).map((n,i)=>`${i+1}. ${m.items[n]}`));if(m.type==='psu')lines.push(...m.readings.map((v,i)=>`${v.rail}: ${v.value} V → ${({inside:'Dentro del intervalo',outside:'Fuera del intervalo'})[r.answers['r'+i]]||'Sin clasificar'}`));if(m.type==='report')lines.push(...reportChecks.map((s,i)=>(r.checks[i]?'✓ ':'Pendiente: ')+s));lines.push('Historial de intentos: '+(r.attempts.map(a=>`${a.score}% (${formatDate(a.date)})`).join('; ')||'Sin intentos'));return `<p class="text-block">${esc(lines.join('\n\n'))}</p>`;}
function formatDate(d){return d?new Date(d).toLocaleString('es-CO',{timeZone:'America/Bogota',dateStyle:'medium',timeStyle:'short'}):'Sin guardar';}
function portfolio(){const t=totals();return `${pageHeading('Lo que sabes, con evidencia.','Identifica tu trabajo, revisa tus respuestas y prepara la entrega al instructor.','MI PORTAFOLIO')}<div class="panel"><div class="profile-grid"><label class="field">Nombre o alias del aprendiz<input class="input" data-profile="name" value="${esc(state.profile.name)}" maxlength="100" placeholder="Escribe cómo quieres identificar tu entrega"></label><label class="field">Ficha o grupo<input class="input" data-profile="group" value="${esc(state.profile.group)}" maxlength="100" placeholder="Ej.: Ficha 3532964"></label></div><div class="notice">Modalidad: simulación y análisis de casos. No se requiere abrir un equipo. Tus datos y respuestas permanecen en este navegador; no se envían al instructor automáticamente. No incluyas contraseñas, documentos de identidad ni datos de clientes reales.</div><div class="mini-row"><span>Progreso: ${t.done}/12 misiones · ${t.xp}/1200 XP</span><b>${t.p} %</b></div><div class="progress-line"><span style="width:${t.p}%"></span></div><div class="actions no-print"><button class="btn" data-action="export-report">Descargar entrega HTML ↓</button><button class="btn secondary" data-action="print">Imprimir / Guardar como PDF</button><button class="btn light" data-action="backup">Copia de progreso JSON ↓</button><label class="btn secondary" for="import-file">Restaurar copia JSON ↑</label><input id="import-file" type="file" accept=".json,application/json" hidden></div><p class="help">La entrega HTML incluye tus respuestas, ensayos e informe. Se abre en cualquier navegador y permite imprimir a PDF. La copia JSON sirve para continuar trabajando. Antes de descargar, verifica tu nombre o alias y el grupo.</p></div>${t.done===12?'<div class="achievement">✧ Has completado la ruta de 12 misiones. Prepara tu entrega y contrasta tus conclusiones con el instructor. Este avance es formativo y no acredita una competencia oficial.</div>':''}<div class="panel"><h2>Vista de entrega</h2><p class="muted">${esc(state.profile.name||'Aprendiz sin identificar')} · ${esc(state.profile.group||'Grupo sin indicar')} · ${formatDate(state.updated)}</p><div class="table-wrap"><table><thead><tr><th>Misión</th><th>Resultado actual</th><th>Evidencias</th><th>Estado</th></tr></thead><tbody>${MISSIONS.map(m=>`<tr><td><a href="#mision/${m.id}">${m.id} · ${m.title} ↗</a></td><td>${record(m.id).score===null?'Por verificar':record(m.id).score+' %'}</td><td>${record(m.id).evidence.filter(e=>e.trim().length>=40).length}/3</td><td>${status(m)}</td></tr>`).join('')}</tbody></table></div></div><section class="panel"><h2>Bitácora de las 12 misiones</h2>${MISSIONS.map(m=>`<details class="evidence-item"><summary>${m.id} · ${m.title} <span class="badge">${status(m)}</span></summary>${evidenceContent(m)}</details>`).join('')}</section><div class="no-print"><p class="help">¿Usas un computador compartido? Descarga tu copia y luego borra la sesión para que el siguiente aprendiz empiece su propia ruta.</p><button class="btn danger small" data-action="reset">Borrar los datos de esta ruta en este navegador</button></div>`;}
function resources(){return `${pageHeading('La guía es tu punto de partida.','Consulta, contrasta y regresa al reto. Todo el recorrido tiene una referencia.','BIBLIOTECA Y APOYO')}<div class="resource-grid"><div class="panel"><span class="eyebrow">MATERIAL BASE</span><h2>Guía de Mantenimiento de Equipos de Cómputo</h2><p class="muted">Recurso publicado por jabermudez en GitHub Pages. Esta web propone actividades complementarias originales; no es una copia ni una certificación oficial del recurso.</p><a class="btn" href="${SOURCE}" target="_blank" rel="noopener">Abrir guía completa ↗</a><p class="help" style="margin-top:15px">Revisión de contenidos y estructura: 19 de octubre de 2026. Se consultaron las 15 secciones de la aplicación y su código público. Los enlaces abren la sección de referencia; si la guía no se desplaza, usa su menú.</p></div><div class="panel tip-panel"><div class="eyebrow">LO QUE NECESITAS</div><h2>Un navegador.<br>Curiosidad.<br>Una bitácora.</h2><p class="muted">Puedes realizar toda la ruta desde un celular o computador. Papel y lápiz son opcionales. No necesitas un PC para desarmar, herramientas físicas ni permisos de administrador.</p><div class="notice">Sin equipo disponible: usa los casos y esquemas de las misiones. Si no puedes dibujar, explica con texto la ubicación, el procedimiento o la relación entre componentes.</div></div></div><div class="panel"><h2>Mapa del material y sus misiones</h2>${['introduccion','glosario','taller','motherboard','seguridad','herramientas','protocolo-hardware','simulador-termico','simulador-flujo','sonda-psu','thermal-pads','protocolo-software','diagnostico','procedimientos','checklist'].map(s=>`<div class="source-item"><a href="${SOURCE}#${s}" target="_blank" rel="noopener">${sectionName(s)} ↗</a><span class="muted"> · Misiones ${MISSIONS.filter(m=>m.sections.includes(s)).map(m=>m.id).join(', ')}</span></div>`).join('')}</div><div class="panel readable"><h2>Preguntas de uso</h2>${[['¿Cómo se guarda el avance?','En el almacenamiento local de este navegador, sin cuenta ni servidor. Si cambias de dominio, navegador o dispositivo, restaura una copia JSON. Borrar los datos del sitio o usar navegación privada puede eliminar el avance.'],['¿Puedo trabajar sin conexión?','Los archivos de esta web se pueden abrir localmente tras descargar y descomprimir el ZIP. Las actividades no requieren internet; la tipografía usa una fuente de respaldo sin conexión. La guía externa sí necesita conexión. La versión alojada no garantiza uso sin conexión si no la has descargado.'],['¿Qué entrego al instructor?','El HTML descargado desde Mi portafolio o el PDF generado con Imprimir. Añade la copia JSON si tu instructor la solicita. La entrega se realiza por el medio que él indique. No existe envío automático ni panel de seguimiento remoto.'],['¿Qué significa el 80 %?','Es el criterio formativo de la actividad autocorregible. Las explicaciones escritas solo se comprueban por extensión; el instructor evalúa su precisión, razonamiento y pertinencia con la rúbrica.'],['¿Puedo hacer mantenimiento real en casa?','Esta ruta se resuelve íntegramente mediante simulación. La práctica física debe organizarse como una actividad distinta, con autorización, supervisión, manual del modelo y condiciones de seguridad adecuadas.'],['¿Qué hago si no se guarda?','Descarga de inmediato una copia JSON y comprueba que el archivo exista. Conserva también la entrega HTML. El navegador avisará si una escritura en el almacenamiento falla.']].map(([q,a])=>`<details class="source-item"><summary><strong>${q}</strong></summary><p class="muted" style="margin-top:12px">${a}</p></details>`).join('')}</div>`;}
function render(){const route=location.hash.slice(1)||'inicio',m=currentMission();$('#main').innerHTML=m?lesson(m):route==='misiones'?missionList():route==='portafolio'?portfolio():route==='recursos'?resources():dashboard();$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===(m?'misiones':['inicio','misiones','portafolio','recursos'].includes(route)?route:'inicio');a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.title=m?`${m.title} · Bitácora PC`:'Bitácora PC · Laboratorio en casa';if(m&&['thermal','airflow'].includes(m.type))updateSim(m);}
document.addEventListener('input',event=>{const el=event.target,m=currentMission();if(el.id==='search'){query=el.value;$('#mission-results').innerHTML=filteredCards();return;}if(el.dataset.profile){state.profile[el.dataset.profile]=el.value;save();return;}if(!m)return;const r=record(m.id);if(el.dataset.evidence!==undefined){const i=Number(el.dataset.evidence);r.evidence[i]=el.value;save();$(`[data-evidence-count="${i}"]`).textContent=el.value.trim().length+'/40 caracteres mínimo';updateCompletion(m);}if(el.dataset.report!==undefined){const i=Number(el.dataset.report);r.report[i]=el.value;invalidate(m);save();$(`[data-report-count="${i}"]`).textContent=el.value.trim().length+'/40 caracteres mínimo';}if(el.dataset.sim){r.sim[el.dataset.sim]=el.value;invalidate(m);save();updateSim(m);}});
document.addEventListener('change',async event=>{const el=event.target,m=currentMission();if(el.id==='import-file'){await importBackup(el.files[0]);el.value='';return;}if(!m)return;const r=record(m.id);if(el.dataset.answer){const key=el.dataset.answer;r.answers[key]=el.type==='radio'?Number(el.value):el.value;if(m.type==='case'){const i=Number(key.slice(1));r.seen=r.seen.filter(n=>n<i);Object.keys(r.answers).filter(k=>k.startsWith('q')&&Number(k.slice(1))>i).forEach(k=>delete r.answers[k]);}invalidate(m);save();if(m.type==='case'){const target=el.name;$('#activity').innerHTML=`<h2>02 / Resuelve el reto</h2>${activity(m)}<div class="actions"><button class="btn" data-action="grade">Verificar mi trabajo →</button></div><div id="grade-summary" class="feedback" aria-live="polite"></div>`;const focus=$(`input[name="${target}"]:checked`);focus?.focus();}}if(el.dataset.check!==undefined){r.checks[Number(el.dataset.check)]=el.checked;invalidate(m);save();}});
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-action]');if(!el)return;const m=currentMission();if(el.dataset.filter){filter=el.dataset.filter;render();return;}if(el.dataset.board!==undefined){const i=Number(el.dataset.board);const text=['Zona central: soporte del procesador. Verifica modelo, orientación y compatibilidad.','Ranuras largas de memoria junto al procesador. La prioridad de instalación se consulta en el manual.','Conector de expansión largo para una tarjeta, como una GPU. Libera el seguro antes de retirarla.','Conector compacto para unidades compatibles. M.2 describe un formato; la interfaz depende del modelo.','Etapas de regulación de tensión cerca de la CPU. No se deduce su estado solo por una temperatura genérica.','Pines de pulsadores e indicadores. Requieren el diagrama exacto de la placa.'];$('#board-hint').textContent=`${i+1}. ${m.pairs[i][0]} · ${text[i]}`;return;}if(el.dataset.command!==undefined){const c=CONSOLE_COMMANDS[Number(el.dataset.command)];$('#terminal-output').textContent=`SIMULACIÓN · No se ejecutó ningún comando\n\n> ${c.cmd}\n\n${c.out}`;$('#command-note').textContent=c.note;return;}if(el.dataset.move!==undefined&&m){const r=record(m.id),i=Number(el.dataset.move),j=i+Number(el.dataset.dir);if(j<0||j>=r.order.length)return;[r.order[i],r.order[j]]=[r.order[j],r.order[i]];invalidate(m);save();const container=$('.order-list');const holder=document.createElement('div');holder.innerHTML=orderBlock(m);container.replaceWith($('.order-list',holder));$(`[data-move="${j}"][data-dir="${j===0?1:-1}"]`)?.focus();return;}if(el.dataset.case!==undefined&&m){const i=Number(el.dataset.case),r=record(m.id);if(r.answers['q'+i]===m.questions[i].answer){if(!r.seen.includes(i))r.seen.push(i);save();render();const q=$$('.case-step');q[Math.min(i+1,q.length-1)]?.scrollIntoView({block:'center',behavior:'smooth'});toast('Decisión justificada. Se reveló una nueva pista.');}else{const feedback=$('#feedback-q'+i);feedback.className='feedback bad';feedback.textContent='Revisa el síntoma y prioriza una comprobación pertinente de menor intervención. Elige otra acción para continuar.';}return;}
  switch(el.dataset.action){case 'grade':grade(m);break;case 'save-evidence':save();updateCompletion(m);toast(complete(m)?'Misión completada. Avance actualizado.':'Evidencia guardada. Revisa los pasos pendientes.');break;case 'trial':{const r=record(m.id),v=simValues(m);if(r.trials.some(t=>JSON.stringify(t)===JSON.stringify(v))){toast('Esa configuración ya está registrada. Cambia una variable.');break;}if(r.trials.length>=20){toast('Ya hay 20 pruebas guardadas. Compara las configuraciones existentes.');break;}r.trials.push(v);invalidate(m);save();$('#trial-table').innerHTML=trialTable(m);toast('Configuración registrada. Compara su resultado.');break;}case 'backup':download(JSON.stringify(state,null,2),'bitacora-pc-progreso.json','application/json');toast('Copia JSON preparada. Comprueba tu carpeta de descargas.');break;case 'export-report':exportReport();break;case 'print':$$('#main details').forEach(d=>d.open=true);window.print();break;case 'reset':if(confirm('¿Borrar el progreso de las 12 misiones en este navegador? Descarga primero una copia JSON si deseas conservarlo.')){state=fresh();save();render();toast('La ruta está lista para otro aprendiz.');}break;}
});
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportReport(){const t=totals(),content=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portafolio · Bitácora PC</title><style>body{max-width:900px;margin:40px auto;padding:0 24px;font:15px/1.7 Arial,sans-serif;color:#203c2a}h1{font-size:30px}h2{border-bottom:1px solid #bdcbb8;padding-bottom:9px}h3{margin-top:30px}h4{font-size:14px}p{white-space:pre-wrap;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%;font-size:12px}td,th{border:1px solid #d6dfce;padding:9px;text-align:left}.help{font-size:12px;color:#5d7056}.evidence-item{border-top:2px solid #d6dfce;margin-top:24px;padding-top:14px}.notice{background:#f1f5e9;padding:15px}details{margin:15px 0}a{color:#3f6934}@media print{body{margin:0;padding:0;font-size:10pt}h3,h4{break-after:avoid}table{font-size:9pt}}</style><h1>Bitácora PC · Portafolio de aprendizaje</h1><p><strong>Aprendiz:</strong> ${esc(state.profile.name||'Sin identificar')}<br><strong>Ficha / grupo:</strong> ${esc(state.profile.group||'Sin indicar')}<br><strong>Exportación:</strong> ${formatDate(new Date().toISOString())}<br><strong>Modalidad:</strong> Simulación y análisis de casos</p><p class="notice">Avance: ${t.done}/12 misiones · ${t.xp}/1200 XP. Los resultados automáticos son formativos. Las explicaciones requieren revisión del instructor. Este documento no es un certificado ni acredita una intervención real.</p><h2>Registro de actividades</h2>${MISSIONS.map(evidenceContent).join('')}<h2>Fuente de formación</h2><p><a href="${SOURCE}">Guía de Mantenimiento de Equipos de Cómputo</a> · jabermudez · revisión del recurso: 19 de octubre de 2026.<br>Actividades complementarias: Bitácora PC. Entrega este archivo por el medio indicado por tu instructor. Para generar PDF: abre el archivo y usa Imprimir → Guardar como PDF.</p></html>`;download(content.replaceAll('<details>','<details open>'),'bitacora-pc-entrega.html','text/html');toast('Entrega HTML preparada con respuestas, ensayos e informe.');}
function validateBackup(input){if(!input||input.version!==1||typeof input.profile!=='object'||!input.profile||typeof input.missions!=='object'||!input.missions||Array.isArray(input.missions))throw Error('Formato incompatible.');const safe=fresh();const textValue=(v,max=6000)=>typeof v==='string'?v.slice(0,max):'';safe.profile={name:textValue(input.profile.name,100),group:textValue(input.profile.group,100),mode:'Simulación'};safe.updated=typeof input.updated==='string'&&Number.isFinite(Date.parse(input.updated))?input.updated:null;
  MISSIONS.forEach(m=>{const src=input.missions[m.id];if(!src||typeof src!=='object')return;const target={answers:{},evidence:[0,1,2].map(i=>textValue(src.evidence?.[i])),score:null,attempts:[],trials:[],report:[0,1,2,3,4,5].map(i=>textValue(src.report?.[i])),checks:[0,1,2,3].map(i=>src.checks?.[i]===true),order:null,sim:{},seen:[]};
    if(src.answers&&typeof src.answers==='object'){if(m.questions)m.questions.forEach((q,i)=>{const val=src.answers['q'+i];if(Number.isInteger(val)&&val>=0&&val<q.options.length)target.answers['q'+i]=val;});if(m.pairs)m.pairs.forEach((_,i)=>{const val=src.answers['p'+i];if(m.pairs.some(p=>p[1]===val))target.answers['p'+i]=val;});if(m.readings)m.readings.forEach((_,i)=>{const val=src.answers['r'+i];if(['inside','outside'].includes(val))target.answers['r'+i]=val;});}
    if(Array.isArray(src.order)&&src.order.length===6&&new Set(src.order).size===6&&src.order.every(n=>Number.isInteger(n)&&n>=0&&n<6))target.order=[...src.order];
    if(Array.isArray(src.seen))target.seen=[...new Set(src.seen.filter(n=>Number.isInteger(n)&&n>=0&&n<4))];
    if(src.sim&&typeof src.sim==='object'){for(const k of ['coverage','intake','exhaust']){const n=Number(src.sim[k]);if(Number.isFinite(n)&&n>=20&&n<=(k==='coverage'?100:160)&&n%10===0)target.sim[k]=String(n);}for(const k of ['clean','even'])if(['0','1'].includes(src.sim[k]))target.sim[k]=src.sim[k];}
    if(Array.isArray(src.trials))for(const trial of src.trials.slice(0,20)){if(!trial||typeof trial!=='object')continue;let t;if(m.type==='thermal'&&Number.isInteger(trial.coverage)&&trial.coverage>=20&&trial.coverage<=100&&trial.coverage%10===0&&typeof trial.clean==='boolean'&&typeof trial.even==='boolean')t={coverage:trial.coverage,clean:trial.clean,even:trial.even};if(m.type==='airflow'&&['intake','exhaust'].every(k=>Number.isInteger(trial[k])&&trial[k]>=20&&trial[k]<=160&&trial[k]%10===0))t={intake:trial.intake,exhaust:trial.exhaust};if(t&&!target.trials.some(v=>JSON.stringify(v)===JSON.stringify(t)))target.trials.push(t);}
    if(Array.isArray(src.attempts))target.attempts=src.attempts.slice(-50).filter(a=>a&&Number.isInteger(a.score)&&a.score>=0&&a.score<=100&&typeof a.date==='string'&&Number.isFinite(Date.parse(a.date))).map(a=>({score:a.score,date:a.date}));
    if(Number.isInteger(src.score)&&src.score>=0&&src.score<=100)target.score=src.score;safe.missions[m.id]=target;});return safe;
}
async function importBackup(file){if(!file)return;if(file.size>2*1024*1024){toast('La copia supera 2 MB. Selecciona un JSON de Bitácora PC.');return;}try{const restored=validateBackup(JSON.parse(await file.text()));if(!confirm('Restaurar esta copia reemplazará el avance actual de este navegador. ¿Continuar?'))return;state=restored;MISSIONS.forEach(m=>{const r=record(m.id);if(r.score!==null){if(m.type==='order'&&!r.order)r.score=null;else r.score=evaluate(m).score;}});save();render();toast('Copia restaurada. Los resultados se recalcularon con tus respuestas.');}catch{toast('No se pudo leer la copia. Usa un JSON de progreso de Bitácora PC, versión 1.');}}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
render();
